package org.mockito.internal.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Timer_Timer_TriageGen1Test {

    @Test
    public void testConstructorAndIsCountingInitially() {
        long duration = 1000L;
        Timer timer = new Timer(duration);

        // Verify that the object is created and initial state is false
        assertNotNull(timer);
        assertFalse("Timer should not be counting before start() is called", timer.isCounting());
    }








}

package org.mockito.internal.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Timer_Timer_TriageGen1Test {



    @Test
    public void testStartAndIsCounting() {
        long duration = 500L;
        Timer timer = new Timer(duration);

        // Verify state before start
        assertFalse(timer.isCounting());

        // Execute start
        timer.start();

        // Verify state after start
        assertTrue("Timer should be counting after start() is called", timer.isCounting());
    }






}

