package org.mockito.internal.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Timer_Timer_TriageGen1Test {









    @Test
    public void testMultipleStartCalls() {
        Timer timer = new Timer(100L);

        timer.start();
        assertTrue(timer.isCounting());

        // Calling start again should not break the state
        timer.start();
        assertTrue(timer.isCounting());
    }
}
